using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Threading;

class Release103Tests {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,message);}
 static Settings Fixture(){return new Settings{schemaVersion=2,token="test-phone",pairingKey="test-legacy",columns=5,rows=3,keepAwake=false,speakerSlot=0,micSlot=1,pageCount=1,landscapePageCount=1,portraitPageCount=1,devices=new List<PairedDevice>(),apps=new List<AppEntry>{
  new AppEntry{id="fixture-landscape",orientation="landscape",name="横コピー",type="hotkey",category="common",action="common-copy",iconKey="copy"},
  new AppEntry{id="fixture-portrait",orientation="portrait",name="縦貼り付け",type="hotkey",category="common",action="common-paste",iconKey="paste"}
 }};}
 static void Set(string name,object value){typeof(Program).GetField(name,BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,value);}
 static void Unit(){
  var legacy=Fixture();legacy.apps=new List<AppEntry>{new AppEntry{id="legacy",name="旧設定",type="hotkey",category="common",action="common-copy",iconKey="copy",landscape=new TilePosition{page=0,row=1,column=3},portrait=new TilePosition{page=0,row=2,column=1}}};Set("config",legacy);typeof(Program).GetMethod("SplitOrientationApps",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);legacy=(Settings)typeof(Program).GetField("config",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);Check(legacy.apps.Count==2&&legacy.apps[0].orientation=="landscape"&&legacy.apps[1].orientation=="portrait","Legacy split count");Check(legacy.apps[0].portrait==null&&legacy.apps[1].landscape==null&&legacy.apps[0].id!=legacy.apps[1].id,"Legacy split isolation");
  var s=Fixture();DeckLayout.Migrate(s);DeckLayout.Validate(s);var landscape=s.apps[0];var portrait=s.apps[1];Check(landscape.landscape.column==2&&landscape.portrait==null&&portrait.portrait.column==2&&portrait.landscape==null,"Independent orientation migration");
  Check(s.landscapeColumns==5&&s.landscapeRows==3&&s.portraitColumns==3&&s.portraitRows==5,"Legacy grid migration");Check(landscape.labelOpacity==45&&portrait.labelOpacity==45,"Label opacity migration");landscape.labelOpacity=0;DeckLayout.Validate(s);landscape.labelOpacity=45;
  landscape.landscape=new TilePosition{page=0,row=1,column=3};landscape.size=2;portrait.portrait=new TilePosition{page=0,row=2,column=1};portrait.size=2;DeckLayout.Validate(s);
  landscape.landscape.column=4;Reject(()=>DeckLayout.Validate(s),"Overflow accepted");landscape.landscape.column=3;
  s.landscapeMicSlot=2;s.landscapeSpeakerSize=2;DeckLayout.Validate(s);Check(s.portraitMicSlot==1&&s.portraitSpeakerSize==1,"Landscape fader leaked to portrait");s.landscapeMicSize=2;Reject(()=>DeckLayout.Validate(s),"Landscape fader collision accepted");s.landscapeMicSize=1;s.landscapeSpeakerSize=1;s.landscapeMicSlot=1;
  s.portraitSpeakerSlot=0;s.portraitSpeakerSize=2;s.portraitMicSlot=2;s.portraitMicSize=1;DeckLayout.Validate(s);Check(s.landscapeSpeakerSize==1&&s.landscapeMicSlot==1,"Portrait fader leaked to landscape");s.portraitMicSize=2;Reject(()=>DeckLayout.Validate(s),"Portrait fader overflow accepted");s.portraitSpeakerSize=1;s.portraitMicSize=1;s.portraitMicSlot=1;
  s.apps.Add(new AppEntry{name="collision",orientation="landscape",size=1,fontSize=11,iconScale=82,landscape=new TilePosition{page=0,row=2,column=4}});Reject(()=>DeckLayout.Validate(s),"Overlap accepted");s.apps.RemoveAt(2);
  landscape.landscape.page=3;Check(DeckLayout.Pages(s,"landscape")==4,"Explicit landscape pages");Check(DeckLayout.Pages(s,"portrait")==1,"Portrait page count leaked");s.apps.Clear();Check(DeckLayout.RequiredPages(s,"landscape")==1,"Empty layout");
  var resized=Fixture();DeckLayout.Migrate(resized);resized.apps[0].size=2;resized.apps[0].landscape=new TilePosition{page=0,row=0,column=3};resized.landscapeSpeakerSlot=0;resized.landscapeSpeakerSize=2;resized.landscapeMicSlot=2;resized.landscapeMicSize=1;resized.landscapeColumns=4;resized.landscapeRows=3;DeckLayout.Reflow(resized,"landscape",5);DeckLayout.Validate(resized);Check(resized.landscapeColumns==4&&resized.landscapeRows==3&&resized.portraitColumns==3&&resized.portraitRows==5,"Orientation grid isolation");Check(resized.apps[0].landscape.row==1&&resized.apps[0].landscape.column==2,"4-cell tile was not moved to a valid empty area");
  Set("config",s);var validateEntry=typeof(Program).GetMethod("ValidateEntry",BindingFlags.NonPublic|BindingFlags.Static);Reject(()=>validateEntry.Invoke(null,new object[]{new AppEntry{name="unknown",type="unknown",orientation="landscape",size=1}}),"Unknown widget became an executable app");var clock=new AppEntry{name="clock",type="clock",orientation="landscape",size=2,path="C:\\private.exe",text="private"};validateEntry.Invoke(null,new object[]{clock});Check(clock.path==""&&clock.text==""&&clock.options!=null,"Display widget private fields were not cleared");
  Check(ShortcutKeys.ParseCombo("Ctrl+Shift+M").Length==3,"Custom combo");Reject(()=>ShortcutKeys.ParseCombo("Ctrl+Alt+Delete"),"SAS allowed");Reject(()=>ShortcutKeys.ParseCombo("Ctrl+M+N"),"Multiple keys allowed");Reject(()=>ShortcutKeys.ParseCombo("Ctrl+RunScript"),"Unknown key allowed");Reject(()=>ShortcutKeys.ValidateOverride("audio-mic-up","Ctrl+M"),"Audio override allowed");
  var request=Pairing.Start("テスト端末","test-address");Check(!Pairing.Authorized(s,"Bearer "+request.secret),"Pending secret grants control");Reject(()=>Pairing.Poll(request.id,"wrong"),"Other client can poll");Reject(()=>Pairing.Decide(s,request.id,"wrong",true),"Wrong code approved");Pairing.Decide(s,request.id,request.code,true);Check(Pairing.Authorized(s,"Bearer "+request.token),"Approved token rejected");Check(s.devices[0].credentialHash!=request.token,"Plaintext stored");Pairing.Revoke(s,request.id);Check(!Pairing.Authorized(s,"Bearer "+request.token),"Revoked token accepted");
  var expired=Pairing.Start("expired","expiry");expired.expires=DateTime.UtcNow.AddSeconds(-1);Reject(()=>Pairing.Poll(expired.id,expired.secret),"Expired request accepted");
  Pairing.Start("rate1","rate");Pairing.Start("rate2","rate");Pairing.Start("rate3","rate");Reject(()=>Pairing.Start("rate4","rate"),"Rate limit missing");
  Console.WriteLine("PASS 1.04: independent grids, 4-cell reflow, label opacity, orientations, keys, approval and rate limits");
 }
 public static int Main(string[] args){try{if(args.Length==0){Unit();return 0;}if(args[0]=="validate"){var actual=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<Settings>(System.IO.File.ReadAllText(args[1]));if(actual.apps==null)actual.apps=new List<AppEntry>();if(actual.devices==null)actual.devices=new List<PairedDevice>();int legacy=actual.apps.FindAll(a=>a.orientation!="landscape"&&a.orientation!="portrait").Count,expectedLandscape=legacy+actual.apps.FindAll(a=>a.orientation=="landscape").Count,expectedPortrait=legacy+actual.apps.FindAll(a=>a.orientation=="portrait").Count;Set("config",actual);typeof(Program).GetMethod("SplitOrientationApps",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);actual=(Settings)typeof(Program).GetField("config",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);DeckLayout.Migrate(actual);DeckLayout.Validate(actual);Check(actual.apps.FindAll(a=>a.orientation=="landscape").Count==expectedLandscape,"Landscape migration count");Check(actual.apps.FindAll(a=>a.orientation=="portrait").Count==expectedPortrait,"Portrait migration count");Console.WriteLine("PASS existing 1.02/early 1.03 settings split into independent orientations without changing the source file");return 0;}var s=Fixture();DeckLayout.Migrate(s);Set("config",s);Set("admin","test-admin");Set("lan",new LanNetwork(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"network.json")));var listener=new TcpListener(IPAddress.Loopback,18782);listener.Start();Console.WriteLine("READY 18782");var handle=typeof(Program).GetMethod("Handle",BindingFlags.NonPublic|BindingFlags.Static);while(true){var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(delegate{try{handle.Invoke(null,new object[]{client});}catch{client.Close();}});}}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
